import { IsString, IsNotEmpty, Length, Matches } from "class-validator";

const BASE58_RE = /^[1-9A-HJ-NP-Za-km-z]{32,88}$/;

export class SubmitPaymentDto {
  @IsString()
  @IsNotEmpty()
  quoteId!: string;

  /** Solana Pay reference pubkey (base58) generated by the client */
  @IsString()
  @IsNotEmpty()
  @Matches(BASE58_RE, { message: "reference must be a base58 Solana public key" })
  reference!: string;

  /** Transaction signature returned by Phantom after signing */
  @IsString()
  @IsNotEmpty()
  @Length(64, 128)
  signature!: string;

  /** Customer wallet public key (base58) */
  @IsString()
  @IsNotEmpty()
  @Matches(BASE58_RE, { message: "customerWallet must be a base58 Solana public key" })
  customerWallet!: string;
}
